func mailAllowlistServersLimited(list models.MailAllowlistAdminData) bool {
	return len(list.Servers) > 0 || list.Gmail || list.Outlook
}

// mailListServersLimited is whether a list's servers limit connections:
// any server listed, or Gmail or Outlook let in alone.
func mailListServersLimited(servers []string, gmail, outlook bool) bool {
	return len(servers) > 0 || gmail || outlook
}

